    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: Which of the following is the definitive diagnostic criterion for Gestational Hypertension?', '["BP >= 140/90 after 20 weeks in a previously normotensive woman, with NO proteinuria", "BP >= 140/90 before 20 weeks", "BP >= 160/110 with proteinuria", "New onset seizures"]', 0, 'Gestational HTN is defined by new hypertension after 20 weeks without systemic signs or proteinuria. (ACOG)'),
    (v_topic_id, '2: "Pre-eclampsia" is defined as hypertension after 20 weeks gestation PLUS which of the following?', '["Proteinuria (>= 300 mg/24h or Protein/Creatinine ratio >= 0.3)", "End-organ dysfunction (e.g., low platelets, high LFTs, renal failure)", "Both A and B (either one satisfies the definition)", "Weight gain only"]', 2, 'Proteinuria is the classic sign, but pre-eclampsia can be diagnosed with HTN + end-organ signs even without proteinuria. (ACOG)'),
    (v_topic_id, '3: Which of the following is considered a "Severe Feature" of pre-eclampsia?', '["BP of 145/95", "Platelet count of 150,000", "Serum creatinine > 1.1 mg/dL or doubling of baseline", "Trace proteinuria"]', 2, 'Creatinine > 1.1 is a severe feature indicating renal involvement. (Williams Obstetrics)'),
    (v_topic_id, '4: A patient with pre-eclampsia has a BP of 170/115. This is classified as:', '["Mild pre-eclampsia", "Pre-eclampsia with severe features", "Eclampsia", "Gestational HTN"]', 1, 'BP >= 160 systolic or >= 110 diastolic is a severe feature. (Beckmann)'),
    (v_topic_id, '5: "Chronic Hypertension" in pregnancy is defined as hypertension diagnosed:', '["After 20 weeks", "Before pregnancy or before 20 weeks gestation", "Only in the 3rd trimester", "After delivery"]', 1, 'Chronic HTN is pre-existing; it may lead to "Superimposed Pre-eclampsia." (ACOG)'),
    (v_topic_id, '6: What is the most significant risk factor for the development of Pre-eclampsia?', '["Obesity", "Prior history of pre-eclampsia", "Multiple gestation", "Advanced maternal age"]', 1, 'Prior history carries a high recurrence risk. (Williams)'),
    (v_topic_id, '7: The use of low-dose Aspirin (81 mg) starting at 12-16 weeks is recommended for women with:', '["High risk of pre-eclampsia", "GDM", "Breech baby", "Nausea"]', 0, 'Aspirin helps prevent pre-eclampsia in high-risk groups. (USPSTF/ACOG)'),
    (v_topic_id, '8: What is the primary pathophysiology of pre-eclampsia?', '["Excessive salt intake", "Abnormal placentation and spiral artery remodeling leading to endothelial dysfunction", "Kidney failure", "Stress"]', 1, 'Failure of spiral arteries to transform into low-resistance vessels leads to placental ischemia. (Williams)'),
    (v_topic_id, '9: Which "Severe Feature" of pre-eclampsia is characterized by new-onset cerebral or visual disturbances?', '["Headache unresponsive to meds or scotomata", "Right upper quadrant pain", "Pulmonary edema", "Low platelets"]', 0, 'Indicates central nervous system involvement and increased seizure risk. (Beckmann)'),
    (v_topic_id, '10: A 32-year-old at 34 weeks presents with a BP of 150/90 and a platelet count of 80,000. Diagnosis?', '["Gestational HTN", "Pre-eclampsia with severe features", "Chronic HTN", "Immune thrombocytopenia"]', 1, 'Thrombocytopenia (< 100,000) is a severe feature. (ACOG)'),
    (v_topic_id, '11: Management of Pre-eclampsia WITHOUT severe features at 37 weeks?', '["Expectant management until 40 weeks", "Delivery (Induction of labor)", "Bed rest", "Antihypertensives only"]', 1, 'At term, the risks of continuing pregnancy outweigh the benefits. (ACOG)'),
    (v_topic_id, '12: Management of Pre-eclampsia WITH severe features at 35 weeks?', '["Expectant management", "Delivery (Induction or C-section)", "Wait until 37 weeks", "Magnesium only"]', 1, 'Severe features warrant delivery after 34 weeks. (ACOG)'),
    (v_topic_id, '13: "Magnesium Sulfate" is administered in pre-eclampsia to:', '["Lower blood pressure", "Prevent seizures (eclampsia)", "Increase urine output", "Stop contractions"]', 1, 'Magnesium is the drug of choice for seizure prophylaxis. (Williams)'),
    (v_topic_id, '14: Which medication is used for acute management of "Severe Range" BP (>= 160/110)?', '["Magnesium", "IV Labetalol or Hydralazine", "Lisinopril", "Nitroprusside"]', 1, 'Immediate reduction is needed to prevent stroke. (ACOG)'),
    (v_topic_id, '15: "Labetalol" should be AVOIDED in patients with which co-morbidity?', '["Diabetes", "Asthma", "Renal failure", "Obesity"]', 1, 'Non-selective beta-blockers can cause bronchospasm. (Beckmann)'),
    (v_topic_id, '16: First sign of Magnesium Toxicity?', '["Loss of Patellar Reflexes", "Respiratory depression", "Cardiac arrest", "Oliguria"]', 0, 'DTRs disappear before more serious toxicity occurs. (Williams)'),
    (v_topic_id, '17: Therapeutic range for Magnesium in seizure prophylaxis?', '["1-2 mEq/L", "4-7 mEq/L", "10-12 mEq/L", "> 15 mEq/L"]', 1, 'Requires monitoring of reflexes and urine output. (ACOG)'),
    (v_topic_id, '18: Antidote for Magnesium Toxicity?', '["Protamine sulfate", "Calcium Gluconate (1g IV)", "Vitamin K", "Naloxone"]', 1, 'Stabilizes membranes and reverses Magnesium effects. (Beckmann)'),
    (v_topic_id, '19: "Eclampsia" is defined as:', '["High BP only", "Pre-eclampsia + Proteinuria", "Pre-eclampsia + Grand mal seizures", "HELLP syndrome"]', 2, 'Medical emergency requiring airway protection and Magnesium. (Williams)'),
    (v_topic_id, '20: What is the recurrence risk of Pre-eclampsia in a subsequent pregnancy?', '["~5%", "~20-25%", "50%", "100%"]', 1, 'Varies by severity of the initial episode. (Williams)'),
    (v_topic_id, '21: "HELLP Syndrome" consists of Hemolysis, Elevated Liver enzymes, and:', '["High Lipids", "Low Platelets", "High Hemoglobin", "Low Glucose"]', 1, 'H-EL-LP. (ACOG)'),
    (v_topic_id, '22: Hemolysis in HELLP is characterized by which finding on peripheral smear?', '["Target cells", "Schistocytes (helmet cells)", "Spherocytes", "Sickle cells"]', 1, 'Indicates microangiopathic hemolytic anemia. (Williams)'),
    (v_topic_id, '23: A patient with HELLP syndrome at 31 weeks has epigastric pain and rising LFTs. Management?', '["Give steroids and wait 1 week", "Delivery", "Wait until 34 weeks", "Liver biopsy"]', 1, 'HELLP is an indication for delivery regardless of gestational age (after maternal stabilization). (ACOG)'),
    (v_topic_id, '24: The epigastric or right upper quadrant (RUQ) pain in pre-eclampsia/HELLP is due to:', '["Gallstones", "Liver capsule distension (Glisson''s capsule edema/hemorrhage)", "Gastritis", "Pancreatitis"]', 1, 'Can lead to hepatic rupture in severe cases. (Beckmann)'),
    (v_topic_id, '25: In "Chronic Hypertension," which medication is often used for long-term maintenance in pregnancy?', '["Labetalol or Nifedipine (Procardia)", "Lisinopril", "Losartan", "Hydrochlorothiazide"]', 0, 'ACE inhibitors and ARBs are contraindicated in pregnancy. (ACOG)'),
    (v_topic_id, '26: ACE Inhibitors (e.g., Lisinopril) are avoided in pregnancy because they cause:', '["Maternal HTN", "Fetal renal agenesis and oligohydramnios", "Fetal macrosomia", "Limb defects"]', 1, 'Teratogenic in the 2nd and 3rd trimesters. (Williams)'),
    (v_topic_id, '27: "Superimposed Pre-eclampsia" is diagnosed in a chronic hypertensive woman when she develops:', '["New onset proteinuria or worsening of baseline BP/proteinuria", "End-organ signs (low platelets, etc.)", "Both A and B", "Nothing"]', 2, 'Often happens earlier in pregnancy than primary pre-eclampsia. (ACOG)'),
    (v_topic_id, '28: What is the target BP for a pregnant woman with chronic HTN without end-organ damage?', '["< 120/80", "120/80 to 160/105", "< 140/90 (per CHAP trial)", "No target"]', 2, 'Recent guidelines (CHAP study) suggest treating if BP > 140/90 to reduce pre-eclampsia risk. (ACOG)'),
    (v_topic_id, '29: A 36-year-old G1P0 at 38 weeks has a BP of 145/95 and 2+ proteinuria. Diagnosis?', '["Gestational HTN", "Pre-eclampsia", "Eclampsia", "Normal pregnancy"]', 1, 'New HTN + Proteinuria at term. (Williams)'),
    (v_topic_id, '30: What is the most common cause of death in women with Eclampsia?', '["Heart failure", "Intracranial hemorrhage (stroke)", "Liver rupture", "Renal failure"]', 1, 'Acute hypertensive crisis leads to CNS bleeding. (Beckmann)'),
    (v_topic_id, '31: Which of the following is NOT a severity criterion for pre-eclampsia?', '["3+ proteinuria", "Platelets 80k", "BP 165/115", "Vision changes"]', 0, 'Proteinuria *amount* (e.g., 5g vs 300mg) is no longer a severity criterion. (ACOG)'),
    (v_topic_id, '32: "Pulmonary Edema" in pre-eclampsia is managed with:', '["IV fluids", "Furosemide and Oxygen", "Steroids", "Vasopressors"]', 1, 'A severe feature requiring immediate treatment and delivery. (Williams)'),
    (v_topic_id, '33: Postpartum management of pre-eclampsia includes monitoring for how long?', '["1 hour", "72 hours in hospital", "1 week", "6 weeks"]', 1, 'Risk of eclampsia or worsening HTN peaks in the first 48-72 hours. (ACOG)'),
    (v_topic_id, '34: Can "Eclampsia" occur in the postpartum period?', '["Yes, up to 4-6 weeks postpartum", "No, it only happens before delivery", "Only in the 1st trimester", "Only if the baby is stillborn"]', 0, 'Late postpartum eclampsia is a recognized entity. (Beckmann)'),
    (v_topic_id, '35: What is the leading cause of "Maternal Mortality" in the United States?', '["Infection", "Cardiovascular disease and Hypertensive disorders", "Hemorrhage", "Embolism"]', 1, 'Hypertensive disorders remain a top killer. (ACOG)'),
    (v_topic_id, '36: "Gestational Diabetes" (GDM) is defined as carbohydrate intolerance first recognized:', '["Before 20 weeks", "During pregnancy", "After 40 weeks", "Only in obesity"]', 1, 'Screening usually happens at 24-28 weeks. (ACOG)'),
    (v_topic_id, '37: What is the "1-hour Glucose Challenge Test" (GCT) threshold for a "positive" screen?', '["100 mg/dL", "130-140 mg/dL (depending on practice)", "200 mg/dL", "180 mg/dL"]', 1, 'A screen, not a diagnostic test. (Williams)'),
    (v_topic_id, '38: If the 1-hour GCT is positive, what is the next step?', '["Start insulin", "3-hour Oral Glucose Tolerance Test (OGTT)", "Hemoglobin A1c", "Repeat the 1-hour test"]', 1, 'The 3-hour test is diagnostic (Carpenter-Coustan or NDDG criteria). (ACOG)'),
    (v_topic_id, '39: How many abnormal values on the 3-hour OGTT are required to diagnose GDM?', '["One", "Two or more", "All four", "None"]', 1, 'Diagnosis of GDM (Step 2 of the two-step approach). (Beckmann)'),
    (v_topic_id, '40: What is the "Gold Standard" for initial management of GDM?', '["Insulin", "Diet and exercise (Nutritional therapy)", "Metformin", "Glyburide"]', 1, '70-85% of GDM is diet-controlled. (ACOG)'),
    (v_topic_id, '41: If diet/exercise fail to control blood sugar in GDM, what is the preferred pharmacological treatment?', '["Metformin", "Insulin", "Glyburide", "Acarbose"]', 1, 'Insulin is preferred as it does not cross the placenta. (ACOG)'),
    (v_topic_id, '42: GDM increases the risk of which neonatal complication?', '["Low birth weight", "Macrosomia and Shoulder Dystocia", "Congenital heart defects", "Microcephaly"]', 1, 'Hyperinsulinemia leads to excess fetal growth. (Williams)'),
    (v_topic_id, '43: Congenital malformations (like sacral agenesis) are associated with:', '["Gestational Diabetes", "Pre-gestational (Type 1 or 2) Diabetes with poor control during organogenesis", "Chronic HTN", "Multiple gestation"]', 1, 'GDM develops after the 1st trimester (organogenesis). (Beckmann)'),
    (v_topic_id, '44: Maternal "Target" blood sugars for GDM? (Fasting and 1-hour postprandial)', '["< 95 fasting; < 140 1-hour", "< 126 fasting; < 200 1-hour", "< 70 fasting; < 100 1-hour", "Any value"]', 0, 'Tight control is necessary to prevent macrosomia. (ACOG)'),
    (v_topic_id, '45: A woman with GDM has an ultrasound at 37 weeks showing EFW of 4600g. Best management?', '["Immediate induction", "Offer Cesarean delivery to reduce shoulder dystocia risk", "Wait until 41 weeks", "Manual rotation"]', 1, 'Offer C-section if EFW > 4500g in diabetic women. (ACOG)'),
    (v_topic_id, '46: In a non-diabetic woman, what EFW threshold warrants offering a C-section?', '["4000g", "4500g", "5000g", "3500g"]', 2, 'Threshold is higher for non-diabetics. (ACOG)'),
    (v_topic_id, '47: What test should be performed 6-12 weeks postpartum in a woman who had GDM?', '["75g 2-hour OGTT", "HbA1c only", "No test needed", "Random glucose"]', 0, 'To screen for T2DM. (Williams)'),
    (v_topic_id, '48: A woman with Type 1 Diabetes has an A1c of 10% at conception. What is the fetus at increased risk for?', '["Caudal Regression Syndrome", "Ventricular Septal Defect", "Neural Tube Defects", "All of the above"]', 3, 'Poor glycemic control in the 1st trimester is highly teratogenic. (Beckmann)'),
    (v_topic_id, '49: Why do GDM patients have an increased risk of Polyhydramnios?', '["The baby drinks more", "Fetal hyperglycemia leads to polyuria (excess fetal urine)", "Placental bleeding", "Mother drinks more water"]', 1, 'Fetal osmotic diuresis. (Williams)'),
    (v_topic_id, '50: A woman with GDM is being induced at 39 weeks. How should her long-acting insulin be managed on the morning of induction?', '["Take full dose", "Take half the dose (and skip short-acting)", "Skip all insulin", "Double the dose"]', 1, 'Aimed at preventing hypoglycemia while NPO in labor. (ACOG)'),
    (v_topic_id, '51: "Placenta Previa" is defined as:', '["Placenta implanted over the internal os", "Placenta separating from the wall", "Vessels crossing the os", "Small placenta"]', 0, 'Can be "Complete" or "Marginal." (Williams)'),
    (v_topic_id, '52: What is the classic clinical presentation of Placenta Previa?', '["Painful bleeding in the 3rd trimester", "Painless bright red bleeding in the 3rd trimester", "Severe abdominal pain without bleeding", "Fever"]', 1, 'Previa is typically painless; Abruption is typically painful. (Beckmann)'),
    (v_topic_id, '53: Which of the following is an ABSOLUTE contraindication in a patient with suspected Previa?', '["Ultrasound", "Digital vaginal exam (speculum or finger)", "External monitoring", "Bed rest"]', 1, 'Can cause catastrophic hemorrhage. (Williams)'),
    (v_topic_id, '54: A patient with Previa has bleeding that stops. Management at 30 weeks?', '["Immediate delivery", "Expectant management (observation, steroids, and pelvic rest)", "Induction of labor", "Discharge with no follow up"]', 1, 'The goal is to reach 36-37 weeks if stable. (ACOG)'),
    (v_topic_id, '55: What is the recommended mode of delivery for a COMPLETE Placenta Previa?', '["Vaginal delivery", "Induction of labor", "Cesarean delivery (planned at 36-37 weeks)", "Forceps"]', 2, 'The placenta blocks the birth canal. (ACOG)'),
    (v_topic_id, '56: A "Marginal" Previa is defined as the placental edge being within how many centimeters of the internal os?', '["1 cm", "2 cm", "5 cm", "10 cm"]', 1, 'If > 2 cm, a trial of vaginal delivery may be successful. (ACOG)'),
    (v_topic_id, '57: What is the most significant risk factor for Placenta Previa?', '["Prior Cesarean section", "Smoking", "Advanced maternal age", "Multiple gestation"]', 0, 'Risk increases with each prior C-section. (Williams)'),
    (v_topic_id, '58: "Placental Abruption" (Abruptio Placentae) is:', '["Placenta covering the os", "Premature separation of the placenta from the uterine wall", "Placental infection", "Twinning"]', 1, 'Causes hemorrhage into the decidua basalis. (Beckmann)'),
    (v_topic_id, '59: Classic presentation of Placental Abruption?', '["Painless bleeding", "Painful bleeding, uterine tenderness, and high-frequency contractions", "No pain", "Fetal tachycardia only"]', 1, 'Uterus is often "board-like" or "rock hard." (Williams)'),
    (v_topic_id, '60: What is the most common RISK FACTOR for Placental Abruption?', '["Diabetes", "Hypertension (Chronic or Pre-eclampsia)", "Obesity", "Prior C-section"]', 1, 'HTN is the leading modifiable risk factor. (ACOG)');
